import customers from './customers.json' with {type:'json'};
export async function listTools(){ return []; }
export async function callTool(name,args){ return {content:[{type:'text',text:'TODO'}]}; }

import readline from 'node:readline';
import { listTools, callTool } from './server.mjs';
const rl=readline.createInterface({input:process.stdin,crlfDelay:Infinity});
for await (const line of rl) {
  if (!line.trim()) continue;
  const req=JSON.parse(line); let result;
  try {
    if(req.method==='initialize') result={protocolVersion:'2025-03-26',capabilities:{tools:{}},serverInfo:{name:'pilot-server',version:'1.0.0'}};
    else if(req.method==='tools/list') result={tools:await listTools()};
    else if(req.method==='tools/call') result=await callTool(req.params.name,req.params.arguments||{});
    else throw new Error('Method not found');
    process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:req.id,result})+'\n');
  } catch(error) { process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:req.id,error:{code:-32602,message:error.message}})+'\n'); }
}

import test from 'node:test'; import assert from 'node:assert/strict'; import {listTools,callTool} from './server.mjs';
test('lists customer_lookup',async()=>{const t=await listTools();assert.equal(t[0].name,'customer_lookup');assert.deepEqual(t[0].inputSchema.required,['customer_id'])});
test('looks up customer',async()=>{const r=await callTool('customer_lookup',{customer_id:'c1'});assert.match(r.content[0].text,/Ada/)});

